begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select set_config('setup.cfi',(select id::text from public.profiles where email='pilot.one@example.test'),true);
select set_config('setup.student',(select id::text from public.profiles where email='instructor.one@example.test'),true);
select set_config('setup.other',(select id::text from public.profiles where email='platform.admin@example.test'),true);
select set_config('request.jwt.claim.sub',current_setting('setup.cfi'),true);
set local role authenticated;
select is(public.get_schedule_eligibility()->>'can_instruct','false','empty profile cannot instruct');
select throws_ok($$insert into public.dashboard_preferences(user_id,enabled_feature_ids) values(auth.uid(),array['cfi_schedule']) on conflict(user_id) do update set enabled_feature_ids=excluded.enabled_feature_ids$$,'42501',null,'direct API cannot bypass activation');
reset role;
insert into public.saved_people(id,user_id,role,display_name) values
('53000000-0000-4000-8000-000000000001',current_setting('setup.cfi')::uuid,'self','Schedule Instructor'),
('53000000-0000-4000-8000-000000000002',current_setting('setup.cfi')::uuid,'student','Schedule Student'),
('53000000-0000-4000-8000-000000000003',current_setting('setup.cfi')::uuid,'student','Other Person Certificate');
update public.profiles set self_person_id='53000000-0000-4000-8000-000000000001' where id=current_setting('setup.cfi')::uuid;
insert into public.saved_person_certificates(id,user_id,person_id,certificate_type,certificate_number,ratings,last_event_date) values
('53000000-0000-4000-8000-000000000010',current_setting('setup.cfi')::uuid,'53000000-0000-4000-8000-000000000003','flight_instructor','OTHER',array['ASEL'],current_date),
('53000000-0000-4000-8000-000000000011',current_setting('setup.cfi')::uuid,'53000000-0000-4000-8000-000000000001','pilot','PILOT',array['ASEL'],current_date);
set local role authenticated;
select is(public.get_schedule_eligibility()->>'can_instruct','false','pilot or another person certificate is not sufficient');
update public.saved_person_certificates set certificate_type='ground_instructor',certificate_number=' ' where id='53000000-0000-4000-8000-000000000011';
select is(public.get_schedule_eligibility()->>'can_instruct','false','blank certificate number is incomplete');
update public.saved_person_certificates set certificate_number='GI-123',ratings='{}' where id='53000000-0000-4000-8000-000000000011';
select is(public.get_schedule_eligibility()->>'can_instruct','false','empty ratings are incomplete');
update public.saved_person_certificates set ratings=array['AGI'],last_event_date=null where id='53000000-0000-4000-8000-000000000011';
select is(public.get_schedule_eligibility()->>'can_instruct','false','activity or issuance date required');
update public.saved_person_certificates set last_event_date=current_date where id='53000000-0000-4000-8000-000000000011';
select is(public.get_schedule_eligibility()->>'can_instruct','true','complete own ground instructor information qualifies');
select lives_ok($$insert into public.dashboard_preferences(user_id,enabled_feature_ids) values(auth.uid(),array['cfi_schedule']) on conflict(user_id) do update set enabled_feature_ids=excluded.enabled_feature_ids$$,'qualified instructor can activate');
update public.saved_person_certificates set certificate_type='flight_instructor',ratings=array['ASEL'] where id='53000000-0000-4000-8000-000000000011';
select is(public.get_schedule_eligibility()->>'can_instruct','true','complete own flight instructor information qualifies');
select public.set_cfi_person_access('53000000-0000-4000-8000-000000000002',true);
select public.save_cfi_person_availability(auth.uid(),'53000000-0000-4000-8000-000000000002','America/New_York','weekly',1,null,'[{"start_minute":420,"end_minute":660}]',false);
select public.save_cfi_person_availability(auth.uid(),'53000000-0000-4000-8000-000000000002','America/New_York','weekly',3,null,'[{"start_minute":600,"end_minute":840}]',false);
select public.save_cfi_person_availability(auth.uid(),'53000000-0000-4000-8000-000000000002','America/New_York','date',1,(now() at time zone 'America/New_York')::date,'[]',false);
select is(public.fill_schedule_availability_weeks(auth.uid(),'America/New_York','53000000-0000-4000-8000-000000000002'),27,'whole week fill covers all 28 dates except manual exception');
reset role;
select is((select count(*) from private.cfi_person_availability_override_dates where student_user_id='53000000-0000-4000-8000-000000000002'),28::bigint,'all four weeks include unavailable dates');
select is((select max(availability_date) from private.cfi_person_availability_override_dates where student_user_id='53000000-0000-4000-8000-000000000002'),(now() at time zone 'America/New_York')::date+27,'fill extends to fourth week, not first');
select is((select count(*) from private.cfi_person_availability_slots where student_user_id='53000000-0000-4000-8000-000000000002' and scope='date' and availability_date=(now() at time zone 'America/New_York')::date),0::bigint,'manual unavailable preserved');
select set_config('request.jwt.claim.sub',current_setting('setup.student'),true);
set local role authenticated;
select is(public.get_schedule_eligibility()->>'invited_student','false','unlinked student has no invite access');
select throws_ok($$select public.get_schedule_availability_review(current_setting('setup.cfi')::uuid,'UTC')$$,'42501',null,'unlinked review forbidden');
reset role;
insert into public.saved_person_account_links(saved_person_id,owner_user_id,linked_user_id) values('53000000-0000-4000-8000-000000000002',current_setting('setup.cfi')::uuid,current_setting('setup.student')::uuid);
set local role authenticated;
select is(public.get_schedule_eligibility()->>'invited_student','true','linked granted student qualifies without instructor certificate');
select lives_ok($$insert into public.dashboard_preferences(user_id,enabled_feature_ids) values(auth.uid(),array['cfi_schedule']) on conflict(user_id) do update set enabled_feature_ids=excluded.enabled_feature_ids$$,'invited student can enable');
select is(public.get_schedule_availability_review(current_setting('setup.cfi')::uuid,'America/New_York')->>'needs_review','true','first use needs review');
select throws_ok($$select public.confirm_schedule_availability(current_setting('setup.cfi')::uuid,'UTC',6)$$,'22023',null,'cannot confirm fewer than seven days');
select lives_ok($$select public.confirm_schedule_availability(current_setting('setup.cfi')::uuid,'America/New_York',14)$$,'confirm two weeks');
select is(public.get_schedule_availability_review(current_setting('setup.cfi')::uuid,'America/New_York')->>'needs_review','false','review persists');
select is(public.get_schedule_availability_review(current_setting('setup.cfi')::uuid,'America/New_York')->>'confirmed_through',((now() at time zone 'America/New_York')::date+13)::text,'confirmation uses browser timezone');
select public.save_cfi_person_availability(current_setting('setup.cfi')::uuid,'53000000-0000-4000-8000-000000000002','America/New_York','date',1,(now() at time zone 'America/New_York')::date,'[{"start_minute":600,"end_minute":720}]',false);
select is(public.get_schedule_availability_review(current_setting('setup.cfi')::uuid,'America/New_York')->>'needs_review','true','changing availability invalidates review');
select public.confirm_schedule_availability(current_setting('setup.cfi')::uuid,'America/New_York',14);
select public.clear_cfi_person_date(current_setting('setup.cfi')::uuid,'53000000-0000-4000-8000-000000000002',(now() at time zone 'America/New_York')::date);
select is(public.get_schedule_availability_review(current_setting('setup.cfi')::uuid,'America/New_York')->>'needs_review','true','deleting date override also invalidates review');
select throws_ok($$select * from private.schedule_availability_reviews$$,'42501',null,'review storage not exposed');
select set_config('request.jwt.claim.sub',current_setting('setup.other'),true);
select throws_ok($$select public.confirm_schedule_availability(current_setting('setup.cfi')::uuid,'UTC',14)$$,'42501',null,'outsider cannot confirm');
select throws_ok($$select public.fill_schedule_availability_weeks(current_setting('setup.cfi')::uuid,'UTC','53000000-0000-4000-8000-000000000002')$$,'42501',null,'outsider cannot bulk fill');
reset role;
select ok(not has_function_privilege('anon','public.get_schedule_eligibility()','execute'),'eligibility is authenticated only');
select ok(not has_function_privilege('anon','public.fill_schedule_availability_weeks(uuid,text,uuid)','execute'),'bulk fill is authenticated only');
select * from finish();
rollback;
